{"hypothesis": "Properly unfilter PNG scanlines (bpp=1, row width 32) before XORing the two images.", "code": "
def unfilter(data,w=32,h=256,bpp=1):
    rows=[]; prev=bytearray(w)
    for r in range(h):
        f=data[r*(w+1)]; line=bytearray(data[r*(w+1)+1:(r+1)*(w+1)])
        for i in range(w):
            left=line[i-bpp] if i>=bpp else 0
            up=prev[i]; ul=prev[i-bpp] if i>=bpp else 0
            if f==1: line[i]=(line[i]+left)&255
            elif f==2: line[i]=(line[i]+up)&255
            elif f==3: line[i]=(line[i]+((left+up)>>1))&255
            elif f==4:
                p=left+up-ul; pa=abs(p-left); pb=abs(p-up); pc=abs(p-ul)
                pr=left if pa<=pb and pa<=pc else (up if pb<=pc else ul)
                line[i]=(line[i]+pr)&255
        rows.append(bytes(line)); prev=line
    return rows
A=unfilter(a); B=unfilter(b)
X=[bytes(p^q for p,q in zip(ra,rb)) for ra,rb in zip(A,B)]
def tobits(rows):
    # render as 1-bit png pixels
    out=bytearray()
    for r in rows: out.append(0); out+=r
    return bytes(out)
def chunk(t,c): return struct.pack('>I',len(c))+t+c+struct.pack('>I',zlib.crc32(t+c)&0xffffffff)
for name,rows in [('x_xor.png',X),('a.png',A),('b.png',B)]:
    open('/workspace/'+name,'wb').write(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',256,256,1,0,0,0,0))+chunk(b'IDAT',zlib.compress(tobits(rows)))+chunk(b'IEND',b''))
print('written')
"}

