import zlib, struct
def raw(f):
    d=open('/workspace/'+f,'rb').read()
    i=8; idat=b''
    while i<len(d):
        L,=struct.unpack('>I',d[i:i+4]); t=d[i+4:i+8]; c=d[i+8:i+8+L]
        if t==b'IDAT': idat+=c
        i+=12+L
    return zlib.decompress(idat)
def unfilter(data,w=32,h=256,bpp=1):
    rows=[]; prev=bytearray(w)
    for r in range(h):
        f=data[r*(w+1)]; line=bytearray(data[r*(w+1)+1:(r+1)*(w+1)])
        for i in range(w):
            left=line[i-bpp] if i>=bpp else 0
            up=prev[i]; ul=prev[i-bpp] if i>=bpp else 0
            if f==1: line[i]=(line[i]+left)&255
            elif f==2: line[i]=(line[i]+up)&255
            elif f==3: line[i]=(line[i]+((left+up)>>1))&255
            elif f==4:
                p=left+up-ul; pa=abs(p-left); pb=abs(p-up); pc=abs(p-ul)
                pr=left if pa<=pb and pa<=pc else (up if pb<=pc else ul)
                line[i]=(line[i]+pr)&255
        rows.append(bytes(line)); prev=line
    return rows
A=unfilter(raw('image1.png')); B=unfilter(raw('image2.png'))
def bit(rows,r,c): return (rows[r][c//8]>>(7-c%8))&1
def show(rows,step=4):
    for r in range(0,256,step):
        print(''.join('#' if bit(rows,r,c)==0 else ' ' for c in range(0,256,step//2)))
print("A"); show(A,4)
"}

